import json

# Parse CPC codes and map to level-5 subclass (first 4 chars)
def get_lvl5_codes(cpc_str):
    if not cpc_str:
        return set()
    try:
        items = json.loads(cpc_str)
    except Exception:
        return set()
    codes = set()
    for it in items:
        code = it.get('code', '')
        if not code:
            continue
        # Level 5 is 4-char subclass
        sub = code[:4]
        if sub in lvl5_symbols:
            codes.add(sub)
    return codes

